209:   const found = availableLog(directory, input.sessionId, input.reference);
210:   if (!found) return { status: "unavailable" };
211:   const cursor = input.cursor ?? 0;
212:   if (!Number.isSafeInteger(cursor) || cursor < 0 || cursor > found.size) return { status: "invalid_cursor" };
213:   let fd: number | undefined;
214:   try {
215:     fd = openSync(found.path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
216:     if (!fstatSync(fd).isFile()) return { status: "unavailable" };
217:     if (cursor < found.size) {
218:       const first = Buffer.alloc(1);
219:       readSync(fd, first, 0, 1, cursor);
220:       if ((first[0]! & 0xc0) === 0x80) return { status: "invalid_cursor" };
221:     }
222:     const requested = Number.isSafeInteger(input.maxBytes) ? input.maxBytes! : 8192;
223:     const length = Math.min(found.size - cursor, Math.max(4, Math.min(8192, requested)));
224:     const bytes = Buffer.alloc(length);
225:     const received = readSync(fd, bytes, 0, length, cursor);
226:     let consumed = received;
227:     const decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
228:     let text = "";
