100: /** Preserve complete identities and digests, or reject the entire malformed receipt. */
101: export function validHostFileFacts(value: unknown): HostFileFacts | undefined {
102:   if (!value || typeof value !== "object") return undefined;
103:   const facts = value as HostFileFacts;
104:   const digest = (item: unknown) => item === "missing" || typeof item === "string" && /^sha256:[a-f0-9]{64}$/.test(item);
105:   if (typeof facts.environmentKey !== "string" || !facts.environmentKey || !Array.isArray(facts.files) || !facts.files.length) return undefined;
106:   if (facts.executionRoot !== undefined && (typeof facts.executionRoot !== "string" || !facts.executionRoot)
107:     || facts.pathStyle !== undefined && facts.pathStyle !== "windows" && facts.pathStyle !== "posix") return undefined;
108:   if (!facts.files.every(file => file && typeof file.path === "string" && file.path.length > 0
109:     && typeof file.subjectKey === "string" && file.subjectKey.length > 0
110:     && ["read", "write", "edit", "patch"].includes(file.operation) && file.completed === true
111:     && digest(file.afterDigest) && (file.beforeDigest === undefined || digest(file.beforeDigest))
112:     && (file.operation === "read" || file.beforeDigest !== undefined)
113:     && (file.bodyVisible === undefined || typeof file.bodyVisible === "boolean"))) return undefined;
114:   return facts;
115: }
