4: /**
5:  * LLM 摘要提示词。
6:  * 要求模型先写 <analysis>（草稿/推理），再写 <summary>（正式续聊用摘要）；
7:  * formatSummary 会丢掉 analysis，只保留 summary 内容。
8:  */
9: export const COMPACT_PROMPT = `Summarize the following conversation between the user and an AI assistant.
10: 
11: Produce your summary in two sections:
12: 
13: <analysis>
14: - Briefly describe what the user was trying to accomplish
15: - What approach was taken
16: - Key findings and decisions made
17: - Any errors encountered and how they were resolved
18: </analysis>
19: 
20: <summary>
21: - Concise narrative of the conversation progress
22: - Key state: files modified, tools used, results obtained
23: - Any pending items or follow-up actions needed
24: - The current goal and the latest user constraints, keeping later corrections authoritative
25: - Distinguish confirmed observations, plans, actions not started, and actions with unknown outcomes
26: - Preserve artifact paths and full-result references needed for the next step; an unknown outcome must be checked before repeating an action
27: </summary>
28: 
29: Keep the summary concise and focused on information needed for continuing the task.`;
30: 
31: // -------------------------------------------------------------------------
32: // Compact context 辅助（B.2）
33: // -------------------------------------------------------------------------
34: 
35: /**
36:  * 从消息历史自动提取最近访问的文件路径。
37:  * 扫描 assistant 的 Read / Write / Edit / MultiEdit 工具输入中的 file_path，
38:  * 去重后只保留最近 20 个，供摘要 prompt 的「Recently Accessed Files」段使用。
39:  */
40: export function extractRecentFiles(messages: Message[]): string[] {
41:   const FILE_TOOLS = new Set(["Read", "Write", "Edit", "MultiEdit"]);
42:   const seen = new Set<string>();
43:   const files: string[] = [];
44:   for (const msg of messages) {
45:     if (msg.type === "assistant" && msg.toolUses) {
46:       for (const tu of msg.toolUses) {
47:         if (FILE_TOOLS.has(tu.name)) {
48:           const fp = (tu.input as Record<string, unknown>)?.file_path;
49:           if (typeof fp === "string" && !seen.has(fp)) {
50:             seen.add(fp);
51:             files.push(fp);
52:           }
53:         }
54:       }
55:     }
56:   }
57:   return files.slice(-20);
58: }
59: 
60: /**
61:  * 从消息历史统计工具调用次数，生成 `ToolName×count` 形式的 work log。
62:  * 按调用次数降序，帮助摘要模型理解「本会话主要在做什么」。
63:  */
64: export function deriveWorkLog(messages: Message[]): string | undefined {
65:   const counts = new Map<string, number>();
66:   for (const msg of messages) {
67:     if (msg.type === "assistant" && msg.toolUses) {
68:       for (const tu of msg.toolUses) {
69:         counts.set(tu.name, (counts.get(tu.name) ?? 0) + 1);
70:       }
71:     }
72:   }
73:   if (counts.size === 0) return undefined;
74:   return [...counts.entries()]
75:     .sort((a, b) => b[1] - a[1])
76:     .map(([name, count]) => `${name}×${count}`)
77:     .join(", ");
78: }
