80: /**
81:  * 把 context 拼进 COMPACT_PROMPT。
82:  * 无任何附加上下文时直接返回基础 prompt；有上下文则包在 <context> 中，
83:  * 并提示模型把这些信息写进摘要以便续聊。
84:  */
85: export function buildCompactPrompt(context: CompactContext): string {
86:   const sections: string[] = [];
87:   if (context.sessionMemory) {
88:     sections.push(`## Session Memory Checkpoint\n${context.sessionMemory}`);
89:   }
90:   if (context.taskFocus) {
91:     sections.push(`## Current Task\n${context.taskFocus}`);
92:   }
93:   if (context.recentFiles?.length) {
94:     sections.push(`## Recently Accessed Files\n${context.recentFiles.join("\n")}`);
95:   }
96:   if (context.plan) {
97:     sections.push(`## Current Plan\n${context.plan}`);
98:   }
99:   if (context.workLog) {
100:     sections.push(`## Work Log\n${context.workLog}`);
101:   }
102:   sections.push(...formatSupplementalSections(context.supplementalSections));
103:   if (sections.length === 0) return COMPACT_PROMPT;
104:   return (
105:     COMPACT_PROMPT +
106:     "\n\n<context>\n" +
107:     sections.join("\n\n") +
108:     "\n</context>\n\nIncorporate the above context into your summary to help resume work effectively."
109:   );
110: }
111: 
112: function formatSupplementalSections(
113:   supplementalSections: CompactContextSection[] | undefined,
114: ): string[] {
115:   const sections: string[] = [];
116:   let remainingContentChars = 32_000;
117:   for (const section of supplementalSections ?? []) {
118:     if (sections.length >= 8 || remainingContentChars <= 0) break;
119:     const heading = section.heading
120:       .replace(/[\r\n]+/g, " ")
121:       .trim()
122:       .slice(0, 120);
123:     const content = section.content.trim();
124:     if (!heading || !content) continue;
125:     const boundedContent = content.slice(
126:       0,
127:       Math.min(16_000, remainingContentChars),
128:     );
129:     if (!boundedContent) continue;
130:     sections.push(`## ${heading}\n${boundedContent}`);
131:     remainingContentChars -= boundedContent.length;
132:   }
133:   return sections;
134: }

