102:   // Preserve the existing smaller budget for historical tool observations.
103:   let toolRemaining = 900;
104:   // Recent real user sources get the budget first; noisy tools cannot displace corrections.
105:   const newest = entries.slice().reverse();
106:   for (const entry of [...newest.filter((item) => item.source === "user"), ...newest.filter((item) => item.source === "tool_result")]) {
